<style>
.campus-filters{display:grid;grid-template-columns:1.2fr 1fr 1fr auto;gap:12px;align-items:end;margin:0 0 28px;padding:18px;border:1px solid var(--border);border-radius:20px;background:var(--muted)}.campus-filters label{font-size:13px;font-weight:600}.campus-filters select,.campus-filters input{margin-top:5px}.event-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.event-card{display:flex;flex-direction:column;overflow:hidden;border:1px solid var(--border);border-radius:24px;background:#fff;transition:.35s var(--ease)}.event-card:hover{transform:translateY(-4px);border-color:var(--primary);box-shadow:var(--shadow-elegant)}.event-cover{position:relative}.event-card img{display:block;width:100%;height:225px;object-fit:cover}.event-date-badge{position:absolute;top:15px;left:15px;display:grid;width:64px;height:70px;place-content:center;border-radius:16px;background:#fff;color:var(--foreground);text-align:center;box-shadow:0 9px 25px rgba(0,0,0,.18)}.event-date-badge strong{font:800 28px/1 Sora}.event-date-badge span{margin-top:5px;color:var(--primary-deep);font-size:11px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}.event-info{display:flex;flex:1;flex-direction:column;padding:22px}.event-kicker{color:var(--primary-deep);font-size:12px;font-weight:700;text-transform:uppercase}.event-info h2{margin:10px 0 8px;font-size:21px}.event-info p{color:var(--muted-foreground);font-size:14px;line-height:1.65}.event-more{margin-top:auto;padding-top:12px;color:var(--primary-deep);font-weight:700}.empty-campus{grid-column:1/-1;padding:28px;border:1px solid var(--border);border-radius:20px;background:var(--muted)}@media(max-width:900px){.event-grid{grid-template-columns:repeat(2,1fr)}.campus-filters{grid-template-columns:1fr 1fr}}@media(max-width:620px){.event-grid,.campus-filters{grid-template-columns:1fr}}
</style>
<section class="hero"><div class="wrap"><span class="section-label">— IDEMA Campus</span><h1>Eventi aperti</h1><p>Corsi e incontri dedicati a installatori, progettisti e professionisti del settore.</p></div></section>
<section class="content"><div class="wrap">
<form class="campus-filters" method="get"><label>Stato<select name="stato"><option value="tutti">Tutti</option><?php foreach(['prossimi'=>'Prossimi','passati'=>'Passati','annullati'=>'Annullati'] as $value=>$label): ?><option value="<?=e($value)?>" <?=($filters['status']??'')===$value?'selected':''?>><?=e($label)?></option><?php endforeach; ?></select></label><label>Mese<input type="month" name="mese" value="<?=e($filters['month']??'')?>"></label><label>Categoria<select name="categoria"><option value="">Tutte</option><?php foreach($categories as $category): ?><option value="<?=e($category)?>" <?=($filters['category']??'')===$category?'selected':''?>><?=e($category)?></option><?php endforeach; ?></select></label><button class="btn" type="submit">Filtra</button></form>
<div class="event-grid"><?php $months=['01'=>'GEN','02'=>'FEB','03'=>'MAR','04'=>'APR','05'=>'MAG','06'=>'GIU','07'=>'LUG','08'=>'AGO','09'=>'SET','10'=>'OTT','11'=>'NOV','12'=>'DIC']; ?><?php foreach($events as $event): $timestamp=strtotime((string)$event['starts_at']); ?><a class="event-card" href="/idemaclima/campus/<?=e($event['slug'])?>"><div class="event-cover"><?php if(!empty($event['cover_image'])): ?><img src="<?=e($event['cover_image'])?>" alt="<?=e($event['title'])?>"><?php endif; ?><span class="event-date-badge"><strong><?=date('d',$timestamp)?></strong><span><?=$months[date('m',$timestamp)]?></span></span></div><div class="event-info"><span class="event-kicker"><?=e($event['category']?:'Campus IDEMA')?></span><h2><?=e($event['title'])?></h2><span class="meta"><?=e(date('d/m/Y · H:i',$timestamp))?><?=!empty($event['location'])?' · '.e($event['location']):''?></span><?php if(!empty($event['short_description'])): ?><p><?=e($event['short_description'])?></p><?php endif; ?><span class="event-more">Scopri l’evento →</span></div></a><?php endforeach; ?><?php if(!$events): ?><div class="empty-campus">Nessun evento corrisponde ai filtri selezionati.</div><?php endif; ?></div>
</div></section>
